WoWForeverIT_QuestIT.DataIT[92698] = {
    title = {it = "Qual è il mio scopo?", enHash = "03aaa1bb"},
    reward = {it = "Il costrutto? Vaga per i campi da decenni. Credo da quando gli elementali del vento ci hanno abbandonato. Alvarion sospettava che un tempo trasportasse i raccolti al mercato, o forse si occupasse del bestiame, prima che questo posto diventasse un frutteto. Ma potrebbe essere stato un migliaio di anni fa.\n\nUn tempo, i Plasmavento si occupavano della manutenzione di questi costrutti. Abbiamo pensato di chiedere loro di venire a dargli un'occhiata, ma per noi non è mai stata una questione urgente. Ormai, per lo più, lo ignoriamo.", enHash = "9f3e2eeb"},
}
WoWForeverIT_QuestIT.DataIT[92682] = {
    title = {it = "Renditi utile", enHash = "31cd79a5"},
    progress = {it = "Questi banditi sono più propensi a tradirsi e derubarsi a vicenda che a rubare alla gente comune. Scommetto che, se Ferauu sapesse che alcuni dei suoi hanno agito di propria iniziativa e sono venuti qui in anticipo per sabotare il raccolto, li ucciderebbe lui stesso.", enHash = "b4cf23ee"},
}
